async (intercomElement) => {
            const intercomDoc: OSKBuildingIntercomDocument = intercomElement;
            const intercomId: string = intercomElement.id;

            // Find the specific entry within the intercom's entries
            const entryIndex: number = intercomDoc.intercomEntries.findIndex((entry) => entry.entryId === entryId);
            if (entryIndex === -1) {
                OSKBuildingIntercomService.logger.logWarning(
                    `Entry ${entryId} not found in intercom ${intercomId}, skipping update.`
                );
                return;
            }

            // Get the contactId before modifying the array
            const callTransferListId: string = intercomDoc.intercomEntries[entryIndex].webRTC.contactId;

            // Prepare the updated data for the intercom entry
            const modificationDate: Timestamp = Timestamp.now();
            // create a new array without element at index
            const updatedEntries = intercomDoc.intercomEntries.filter((_, index) => index !== entryIndex);

            // Architectural fix: Use the intercom's internal snapshot of inhabitants to guarantee cleanup,
            // preventing 'not-found' crashes when the unit's source inhabitants have already been deleted.
            const inhabitantsToClean = intercomDoc.intercomEntries[entryIndex].inhabitants || [];
            const userDeletionPromises = inhabitantsToClean.map((inhabitant: OSKIntercomUnitInhabitant) => {
                return OSKUserIntercomService.deleteUserIntercom(inhabitant.userId, intercomId);
            });
            await Promise.all(userDeletionPromises);

            // remove callTransferList from buildings/{buildingId}/callTransferList/{callTransferList}
            await OSKBuildingIntercomCallTransferListController.default.delete(buildingId, callTransferListId);

            // Publish message to update mongodb collection
            await OSKIntercomMessagePublisherService.publishMessageIntercomUpdate({
                ...intercomDoc,
                intercomEntries: updatedEntries,
                modificationDate,
            });

            // Update firebase collection buildings/{buildingId}/intercoms/{intercomId}
            await OSKBuildingIntercomController.default.update(buildingId, intercomId, {
                intercomEntries: updatedEntries,
                modificationDate,
            });

            return;
        }

