            // 2. Update Building Intercom Document & Sync Dénormalized User Views
            const updatedInhabitantsList: OSKIntercomUnitInhabitant[] = (unitEntry.inhabitants || []).filter(
                (i) => i.userId !== deletedUserId
            );
            const modificationDate = Timestamp.now();
            const updatedEntries = [...intercomDoc.intercomEntries];
            updatedEntries[unitEntryIndex] = {
                ...unitEntry,
                inhabitants: updatedInhabitantsList,
