            await OSKIntercomMessagePublisherService.publishMessageIntercomUpdate({
                ...intercomDoc,
                intercomEntries: updatedEntries,
                modificationDate,
            });

            // 4. Save the updated master building intercom document
            return OSKBuildingIntercomController.default.update(buildingId, intercomId, {
                intercomEntries: updatedEntries,
                modificationDate,
            });
