async (building): Promise<OSKBuildingWithDoorsDocument> => {
            const doors = await OSKBuildingDoorController.default.getAll(building.buildingId);

            const doorsWithAcdsPromises = doors.map(async (door) => {
                let acds = await OSKBuildingDoorAccessControlDeviceController.default.getAll(
                    building.buildingId,
                    door.doorId
                );
                // If a type is specified in the request, filter the ACDs
                if (request.accessControlDeviceType) {
                    acds = acds.filter((acd) => acd.accessControlDeviceType === request.accessControlDeviceType);
                }
                return { ...door, accessControlDevices: acds };
            });

            const buildingWithDoorsData = {
                ...building,
                doors: await Promise.all(doorsWithAcdsPromises),
                id: building.id,
            };
            return buildingWithDoorsData;
        }

